use customer_behavior;
select * from customer;
 -- Q1 what is the total revenue generated by male vs female customer?
SELECT 
    gender,
    SUM(`purchase_amount_(usd)`) AS revenue
FROM customer
GROUP BY gender;
-- q2 which customers used a discount but still spent more than the averade purchase amount?
SELECT 
    customer_id,
    `purchase_amount_(usd)`
FROM customer
WHERE discount_applied = 'Yes'
  AND `purchase_amount_(usd)` >= (
      SELECT AVG(`purchase_amount_(usd)`)
      FROM customer
  );
-- Q3 which are the top 5 product with the highest average review rating?
select item_purchased, round(avg(review_rating),2) as "average product rating"
from customer 
group by item_purchased
order by avg(review_rating) desc limit 5;
-- Q4 compare the average purchase amount between express and stabdard shipping
SELECT 
    shipping_type,
    ROUND(AVG(`purchase_amount_(usd)`), 2) AS average_purchase
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;
-- q5 do subcribed customer spend more? comapre average spend and total revenue between subscribes and non-subscribers?
SELECT 
    subscription_status,
    COUNT(customer_id) AS total_customers,
    ROUND(AVG(`purchase_amount_(usd)`), 2) AS avg_spend,
    ROUND(SUM(`purchase_amount_(usd)`), 2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;
-- Q6 which 5 product have the higest percentage or purcahse amount with the discount applied?
SELECT 
    item_purchased,
    ROUND(
        SUM(CASE 
            WHEN discount_applied = 'Yes' THEN 1 
            ELSE 0 
        END) / COUNT(*) * 100,
        2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;
-- q7 segment customer into new , returning, and loyal based on their 
-- total number of previous purchases, and show the count of each segment 
WITH customer_type AS (
    SELECT 
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer
)

SELECT 
    customer_segment,
    COUNT(*) AS `Number of customers`
FROM customer_type
GROUP BY customer_segment;
-- Q8 what are the top 3 most purchased product within each category?
WITH item_counts AS (
    SELECT 
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category 
            ORDER BY COUNT(customer_id) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)

SELECT 
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
ORDER BY category, item_rank;
-- Q9 are customer who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT 
    subscription_status,
    COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;
-- Q10 what is the revenue contribution of each age group?
SELECT 
    age_group,
    SUM(`purchase_amount_(usd)`) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;